-- Georgia. The state had five stops, three of them Halloween attractions.
--
-- This completes the east coast: every state from Maine to Florida now has
-- real depth, and the run inland through Appalachia and the Ohio Valley joins
-- it without a gap.
--
-- Well sourced — gastateparks.org and nps.gov are the top two domains.
--
-- Three dropped. Expedition: Bigfoot! was already here. The peanut monument is
-- held as world-s-largest rather than worlds-largest, so only the second slug
-- convention found it: the seventh time an apostrophe has hidden a duplicate.
-- Dutchy stands at zero metres from the Elberton Granite Museum, outside its
-- door, so he is a feature of a stop in this same batch rather than a stop.
--
-- Cannonball House goes in as cannonball-house-macon, because Lewes, Delaware
-- holds the plain slug. Both were hit by cannonballs; neither is the other.
--
-- Two proximity flags kept: the Capitoline Wolf is fifty metres from the Rome
-- clocktower because Rome, Georgia leans into its name, and the Lion of
-- Atlanta is inside Oakland Cemetery but is a separate thing people visit.
--
-- 157 stops, every one with a source.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, website, timezone, verified_at)
values
  ('Loudermilk Boarding House & Everything Elvis Museum', 'loudermilk-boarding-house-everything-elvis-museum', 'roadside-oddities', 34.51171, -83.52436, 'Cornelia', 'GA', 'A historic boarding house wrapped in an eccentric collection of handmade folk art and Elvis memorabilia assembled by local character Joni Mabe. The property is best known for its Everything Elvis Museum, turning an old Northeast Georgia house into a highly personal roadside shrine.', 'limited', 'https://exploregeorgia.org/cornelia/arts-culture/museums/loudermilk-boarding-house-everything-elvis-museum', null, 'America/New_York', now()),
  ('Old Car City USA', 'old-car-city-usa', 'roadside-oddities', 34.27014, -84.75119, 'White', 'GA', 'A sprawling forest filled with thousands of old vehicles slowly being reclaimed by vines, pine needles and trees. What began as a salvage yard became a walk-through automotive time capsule where rusting cars and wooded trails have effectively merged into one giant outdoor installation.', 'limited', 'https://www.oldcarcityusa.com/', null, 'America/New_York', now()),
  ('Howard Finster''s Paradise Garden', 'howard-finsters-paradise-garden', 'roadside-oddities', 34.51347, -85.31679, 'Summerville', 'GA', 'The visionary folk-art environment created by preacher and artist Howard Finster, packed with mosaics, painted structures, towers, found objects and hand-lettered messages. The garden survives as a preserved artwork rather than a conventional gallery, making it one of Georgia''s essential outsider-art destinations.', 'limited', 'https://paradisegardenfoundation.org/', null, 'America/New_York', now()),
  ('The Rock Garden', 'the-rock-garden', 'roadside-oddities', 34.46289, -84.98266, 'Calhoun', 'GA', 'A miniature fantasy landscape built from stones, shells, concrete and other found materials behind Calhoun Seventh-day Adventist Church. Tiny castles, cathedrals, villages and bridges turn a small garden into an unusually detailed handmade world.', 'open', 'https://exploregeorgia.org/calhoun/outdoors-nature/trails-tours/the-rock-garden', null, 'America/New_York', now()),
  ('School Bus Graveyard', 'school-bus-graveyard', 'roadside-oddities', 34.45254, -83.61669, 'Alto', 'GA', 'Rows of retired school buses covered with large-scale graffiti and mural work form a constantly changing outdoor art environment at a working automotive property. This is not a public abandoned site; visitors should check current access expectations and stay within areas the property permits.', 'limited', 'https://www.spacesarchives.org/explore/search-the-online-collection/school-bus-graveyard/', null, 'America/New_York', now()),
  ('BabyLand General Hospital', 'babyland-general-hospital', 'museums', 34.62198, -83.76176, 'Cleveland', 'GA', 'The elaborate home of Cabbage Patch Kids is staged as a hospital where visitors can watch new dolls being ''born'' beneath the famous Magic Crystal Tree. Even for travelers with no toy nostalgia, the commitment to the fictional hospital setting makes it an unusually surreal roadside experience.', 'limited', 'https://cabbagepatchkids.com/pages/babyland-general-hospital', null, 'America/New_York', now()),
  ('Consolidated Gold Mine', 'consolidated-gold-mine', 'weird-history', 34.53696, -83.97312, 'Dahlonega', 'GA', 'Visitors descend into an actual nineteenth-century hard-rock gold mine beneath Dahlonega and learn how miners followed quartz veins underground. Guided mine tours and gold-panning demonstrations make the surviving tunnels a much stronger OddWay stop than a standard surface museum.', 'limited', 'https://consolidatedgoldmine.com/', null, 'America/New_York', now()),
  ('Crisson Gold Mine', 'crisson-gold-mine', 'weird-history', 34.5572, -83.9669, 'Dahlonega', 'GA', 'A working gold attraction built around historic mining equipment, including a large stamp mill used to crush ore. Visitors can pan for gold and see machinery connected to the region that helped launch America''s first major gold rush.', 'limited', 'https://crissongoldmine.com/', null, 'America/New_York', now()),
  ('Gold Mine Shaft at The Smith House', 'gold-mine-shaft-at-the-smith-house', 'weird-history', 34.53379, -83.98518, 'Dahlonega', 'GA', 'A nineteenth-century mine shaft was discovered beneath this historic inn and restaurant, leaving a literal gold-rush feature under the building. The shaft is displayed as part of the property and gives travelers an unusually direct look at how deeply mining history runs beneath downtown Dahlonega.', 'limited', 'https://smithhouse.com/', null, 'America/New_York', now()),
  ('Dahlonega Gold Museum', 'dahlonega-gold-museum', 'weird-history', 34.53267, -83.98494, 'Dahlonega', 'GA', 'Housed in the old Lumpkin County courthouse, this state historic site explains the 1828 Georgia gold rush, early mining methods and the Dahlonega mint. The building itself stands in the center of the town whose identity was reshaped by the rush.', 'limited', 'https://gastateparks.org/DahlonegaGoldMuseum', null, 'America/New_York', now()),
  ('Fort Mountain Ancient Stone Wall', 'fort-mountain-ancient-stone-wall', 'folklore', 34.75436, -84.70648, 'Chatsworth', 'GA', 'A long, low stone wall snakes across the summit of Fort Mountain, and its original builders and purpose remain uncertain. Archaeologists have rejected many of the more extravagant legends attached to it, but the unexplained prehistoric or early historic structure remains one of North Georgia''s best genuine mysteries.', 'limited', 'https://gastateparks.org/FortMountain', null, 'America/New_York', now()),
  ('Chief Vann House', 'chief-vann-house', 'weird-history', 34.76311, -84.82189, 'Chatsworth', 'GA', 'A preserved 1804 brick plantation home built for Cherokee leader James Vann, whose wealth and complicated history make the site an important window into Cherokee life before forced removal. State interpretation addresses the Vann family, enslaved labor and the upheaval that culminated in the Trail of Tears.', 'limited', 'https://gastateparks.org/ChiefVannHouse', null, 'America/New_York', now()),
  ('New Echota Cherokee Capital', 'new-echota-cherokee-capital', 'weird-history', 34.54043, -84.91003, 'Calhoun', 'GA', 'The reconstructed and archaeological remains of the Cherokee Nation''s capital include the council house, print shop and other structures associated with a sovereign government. The site is directly connected to the Cherokee Phoenix newspaper and the events leading to forced removal.', 'limited', 'https://gastateparks.org/NewEchota', null, 'America/New_York', now()),
  ('Etowah Indian Mounds', 'etowah-indian-mounds', 'weird-history', 34.12815, -84.80795, 'Cartersville', 'GA', 'Six earthen mounds and a large village site preserve a major Mississippian cultural center occupied centuries before European settlement. Visitors can climb designated mounds and see artifacts recovered from the site while learning about the political and ceremonial world centered here.', 'limited', 'https://gastateparks.org/EtowahIndianMounds', null, 'America/New_York', now()),
  ('Hardman Farm Historic Site', 'hardman-farm-historic-site', 'weird-history', 34.68692, -83.70952, 'Sautee Nacoochee', 'GA', 'This preserved farm centers on an Italianate mansion, nineteenth-century outbuildings and the history of the families who lived and worked there. Its position directly beside the Nacoochee mound gives OddWay travelers two visually distinctive historic layers in a single stop.', 'limited', 'https://gastateparks.org/HardmanFarm', null, 'America/New_York', now()),
  ('Nacoochee Indian Mound', 'nacoochee-indian-mound', 'weird-history', 34.68353, -83.70902, 'Sautee Nacoochee', 'GA', 'A large prehistoric mound stands in a pasture beneath a solitary gazebo, creating one of North Georgia''s most recognizable landscapes. The mound predates the gazebo and modern romantic legends attached to the Nacoochee name; view it from lawful public or Hardman Farm access points rather than entering the pasture.', 'roadside', 'https://gastateparks.org/HardmanFarm', null, 'America/New_York', now()),
  ('Track Rock Gap Petroglyph Site', 'track-rock-gap-petroglyph-site', 'weird-history', 34.88203, -83.87792, 'Blairsville', 'GA', 'Six soapstone boulders contain more than a hundred carved figures and symbols created by Indigenous people long before modern settlement. The U.S. Forest Service maintains a short trail and interpretation at the site; visitors should never chalk, trace or touch the carvings.', 'open', 'https://www.fs.usda.gov/r08/chattahoochee-oconee/recreation/track-rock-gap-petroglyph-site', null, 'America/New_York', now()),
  ('Brasstown Bald Observation Tower', 'brasstown-bald-observation-tower', 'roadside-oddities', 34.87428, -83.81083, 'Hiawassee', 'GA', 'Georgia''s highest point is topped by a distinctive observation complex reached from a steep mountain trail or seasonal shuttle. On clear days the view reaches across four states, while the summit''s weather and isolation give it a much stranger atmosphere than a typical roadside overlook.', 'limited', 'https://www.fs.usda.gov/r08/chattahoochee-oconee/recreation/brasstown-bald', null, 'America/New_York', now()),
  ('Foxfire Museum & Heritage Center', 'foxfire-museum-heritage-center', 'weird-history', 34.91141, -83.39607, 'Mountain City', 'GA', 'A collection of relocated Appalachian cabins and traditional structures grew from the student-made Foxfire project that documented mountain craft, folklore and oral history. The museum preserves the physical setting for many of the skills and stories recorded in the famous Foxfire books.', 'limited', 'https://www.foxfire.org/visit-foxfire-village-museum/the-foxfire-museum-mercantile/', null, 'America/New_York', now()),
  ('Original Confederate Flagpole', 'original-confederate-flagpole', 'weird-history', 31.2236, -84.562, 'Blakely', 'GA', 'A tall wooden flagpole in Blakely''s courthouse square was erected in 1861 during the Civil War and has survived into the present landscape. Its endurance makes it an unusual physical relic of the war era rather than a later commemorative monument.', 'open', 'https://dlg.usg.edu/record/dlg_ggpd_s-ga-be200-pt6-bm1-b2013-bc5', null, 'America/New_York', now()),
  ('Trahlyta''s Grave at Stonepile Gap', 'trahlytas-grave-at-stonepile-gap', 'folklore', 34.62759, -83.95435, 'Dahlonega', 'GA', 'Motorists traditionally add stones to this roadside cairn, which local legend identifies as the grave of a Cherokee woman named Trahlyta. Historical scholarship has not established the popular story as authentic Cherokee tradition, so OddWay treats it as a long-running regional legend rather than documented tribal history.', 'roadside', 'https://www.georgiahistory.com/ghmi_marker_updated/trahlytas-grave/', null, 'America/New_York', now()),
  ('Stovall Mill Covered Bridge', 'stovall-mill-covered-bridge', 'weird-history', 34.71172, -83.65779, 'Sautee Nacoochee', 'GA', 'A short nineteenth-century covered bridge spans Chickamauga Creek near Sautee Nacoochee. Its compact scale, weathered timbers and wooded setting make it a worthwhile old-road stop that can be viewed without turning a private ruin into an attraction.', 'open', 'https://exploregeorgia.org/sautee-nacoochee/general/historic-sites-trails-tours/stovall-mill-covered-bridge', null, 'America/New_York', now()),
  ('Toccoa Falls', 'toccoa-falls', 'roadside-oddities', 34.59619, -83.3605, 'Toccoa', 'GA', 'A 186-foot waterfall drops almost vertically behind the campus of Toccoa Falls College. Its unusual height and easy approach make it a dramatic roadside-scale natural stop, while local history also remembers the deadly 1977 Kelly Barnes Dam disaster upstream.', 'limited', 'https://stephenscountyga.gov/toccoa-falls/', null, 'America/New_York', now()),
  ('Currahee Military Museum', 'currahee-military-museum', 'weird-history', 34.57839, -83.33272, 'Toccoa', 'GA', 'Located in Toccoa''s restored railroad depot, the museum preserves the story of the paratroopers who trained at nearby Camp Toccoa before World War II. Exhibits include an original stable from Aldbourne, England, used by members of the 506th Parachute Infantry Regiment.', 'limited', 'https://stephenscountyga.gov/stephens-museums/', null, 'America/New_York', now()),
  ('Camp Toccoa at Currahee', 'camp-toccoa-at-currahee', 'weird-history', 34.55086, -83.39627, 'Toccoa', 'GA', 'The training ground made famous by the paratroopers who ran ''three miles up, three miles down'' Currahee Mountain has been preserved as a historic site. Reconstructed buildings, memorials and trails connect directly to the World War II airborne units trained here.', 'limited', 'https://www.camptoccoaatcurrahee.org/', null, 'America/New_York', now()),
  ('Miles Through Time Automotive Museum', 'miles-through-time-automotive-museum', 'museums', 34.6132, -83.5235, 'Clarkesville', 'GA', 'A nonprofit automotive museum filled with cars, motorcycles, memorabilia and changing displays contributed by multiple collectors. The eclectic, densely packed presentation feels more like walking through several private collections at once than a polished corporate car museum.', 'limited', 'https://milesthroughtime.com/', null, 'America/New_York', now()),
  ('Folk Pottery Museum of Northeast Georgia', 'folk-pottery-museum-of-northeast-georgia', 'roadside-oddities', 34.68398, -83.67435, 'Sautee Nacoochee', 'GA', 'This museum documents the distinctive alkaline-glazed pottery tradition of North Georgia and the families who kept it alive. Face jugs and utilitarian stoneware give the collection an especially strong OddWay fit because many pieces sit halfway between household object and folk creature.', 'limited', 'https://www.folkpotterymuseum.com/', null, 'America/New_York', now()),
  ('Tallulah Gorge', 'tallulah-gorge', 'roadside-oddities', 34.73975, -83.39523, 'Tallulah Falls', 'GA', 'A two-mile-long gorge drops nearly 1,000 feet through the Blue Ridge foothills, crossed by overlooks and a suspension bridge. The state park also preserves the strange history of daredevils and tightrope walkers who turned the chasm into a spectacle.', 'limited', 'https://gastateparks.org/TallulahGorge', null, 'America/New_York', now()),
  ('Rock City Gardens', 'rock-city-gardens', 'roadside-oddities', 34.97393, -85.34888, 'Lookout Mountain', 'GA', 'A classic mountaintop roadside attraction built through giant boulders, narrow passages, caves, gardens and the famous See Seven States overlook. Its Fairyland Caverns and Mother Goose Village preserve the deliberately theatrical mid-century roadside style that makes Rock City more than a scenic overlook.', 'limited', 'https://www.seerockcity.com/', null, 'America/New_York', now()),
  ('Wilder Brigade Monument Tower', 'wilder-brigade-monument-tower', 'weird-history', 34.90744, -85.27244, 'Fort Oglethorpe', 'GA', 'A tall stone observation tower rises over Chickamauga Battlefield as a memorial to Colonel John T. Wilder''s mounted infantry brigade. When tower access is open, visitors can climb the interior staircase for a battlefield view; closures can occur, so check current NPS conditions.', 'limited', 'https://www.nps.gov/chch/learn/historyculture/chickamauga-battlefield.htm', null, 'America/New_York', now()),
  ('Western & Atlantic Railroad Tunnel', 'western-atlantic-railroad-tunnel', 'weird-history', 34.841, -85.0418, 'Tunnel Hill', 'GA', 'A preserved antebellum railroad tunnel passes directly through Chetoogeta Mountain beside a later parallel tunnel. Guided visits connect the underground structure to the Western & Atlantic Railroad and Civil War campaigns that repeatedly fought over this transportation corridor.', 'limited', 'https://civilwarrailroadtunnel.com/plan-your-visit/', null, 'America/New_York', now()),
  ('Prater''s Mill', 'praters-mill', 'weird-history', 34.89516, -84.91933, 'Dalton', 'GA', 'A nineteenth-century water-powered gristmill survives beside Coahulla Creek with its millrace, outbuildings and rural landscape intact. The site is especially atmospheric during public events, but the grounds also preserve an unusually complete picture of a small Southern mill complex.', 'open', 'https://pratersmill.org/', null, 'America/New_York', now()),
  ('Resaca Confederate Cemetery', 'resaca-confederate-cemetery', 'weird-history', 34.60592, -84.94411, 'Resaca', 'GA', 'Created after the 1864 Battle of Resaca, this small cemetery contains the graves of Confederate soldiers gathered from the battlefield. It is often described as one of the earliest Confederate military cemeteries and sits quietly away from the larger battlefield landscape.', 'open', 'https://exploregeorgia.org/resaca/history-heritage/civil-war/resaca-confederate-cemetery', null, 'America/New_York', now()),
  ('Capitoline Wolf Statue', 'capitoline-wolf-statue', 'roadside-oddities', 34.25704, -85.16467, 'Rome', 'GA', 'A bronze copy of Rome''s famous Capitoline Wolf, complete with the infant Romulus and Remus, stands in downtown Rome, Georgia. The Italian government sent the statue in 1929, creating an unexpectedly literal connection between the Georgia city and ancient Roman mythology.', 'open', 'https://romegeorgia.org/capitoline-wolf/', null, 'America/New_York', now()),
  ('Rome Clocktower', 'rome-clocktower', 'weird-history', 34.2575, -85.1647, 'Rome', 'GA', 'A nineteenth-century water tower converted into the city''s iconic clocktower rises above downtown from Neely Hill. Seasonal tours allow visitors inside and up the tower, where the enormous clock mechanism and panoramic view make it more unusual than its skyline silhouette suggests.', 'limited', 'https://romegeorgia.org/city-clocktower/', null, 'America/New_York', now()),
  ('Myrtle Hill Cemetery', 'myrtle-hill-cemetery', 'weird-history', 34.25237, -85.17887, 'Rome', 'GA', 'This terraced cemetery climbs a steep hill above the rivers and contains ornate monuments, veterans'' graves and the burial of Ellen Axson Wilson, the first wife of President Woodrow Wilson. The unusual topography turns the cemetery into a winding hillside landscape rather than a flat burial ground.', 'open', 'https://romegeorgia.org/myrtle-hill-cemetery/', null, 'America/New_York', now()),
  ('Chieftains Museum / Major Ridge Home', 'chieftains-museum-major-ridge-home', 'weird-history', 34.2697, -85.174, 'Rome', 'GA', 'The preserved home of Cherokee leader Major Ridge interprets Cherokee political history, plantation life, enslaved labor and the events surrounding removal. Ridge signed the disputed Treaty of New Echota and was later killed by fellow Cherokees who viewed the treaty as betrayal.', 'limited', 'https://www.chieftainsmuseum.org/', null, 'America/New_York', now()),
  ('Berry College Old Mill', 'berry-college-old-mill', 'roadside-oddities', 34.29356, -85.18553, 'Mount Berry', 'GA', 'A massive wooden overshot waterwheel dominates the old mill complex on Berry College''s mountain campus. The wheel is frequently cited as one of the world''s largest of its type, giving an otherwise pastoral campus a surprisingly oversized piece of machinery.', 'open', 'https://berry.edu/about/our-rich-history/old-mill', null, 'America/New_York', now()),
  ('Rolater Park Cave', 'rolater-park-cave', 'roadside-oddities', 34.10602, -85.33477, 'Cave Spring', 'GA', 'A natural limestone cave opens directly beneath the park in the center of Cave Spring, where cold spring water emerges from underground. Seasonal admission lets visitors walk into the developed portion of the cave; the town''s name is unusually literal.', 'limited', 'https://cavespring.ga.gov/attractions/the-cave-%26-spring-at-rolater-park', null, 'America/New_York', now()),
  ('Barnsley Manor Ruins', 'barnsley-manor-ruins', 'weird-history', 34.3017, -84.9843, 'Adairsville', 'GA', 'The roofless brick shell of Godfrey Barnsley''s nineteenth-century manor remains standing inside the modern Barnsley Resort. War, tornado damage and decades of abandonment reduced the mansion to picturesque ruins that are now preserved as part of the property; visitors should follow resort access rules.', 'limited', 'https://www.barnsleyresort.com/venues/manor-house-ruins-and-pavilion/', null, 'America/New_York', now()),
  ('Allatoona Pass Deep Cut', 'allatoona-pass-deep-cut', 'weird-history', 34.11494, -84.71594, 'Emerson', 'GA', 'A huge hand-cut railroad trench slices through the ridge at Allatoona Pass, where a major Civil War battle was fought in 1864. Trails pass earthworks and the remarkably deep transportation cut, making the engineering itself as visually striking as the battlefield history.', 'open', 'https://gastateparks.org/AllatoonaPassBattlefield', null, 'America/New_York', now()),
  ('Tellus Science Museum', 'tellus-science-museum', 'museums', 34.24111, -84.77139, 'Cartersville', 'GA', 'A large science museum whose collections include dinosaurs, fossils, minerals, historic vehicles and space artifacts. Its gem and mineral galleries and fossil displays make it particularly useful to OddWay as a physical cabinet-of-curiosities stop rather than only a children''s science center.', 'limited', 'https://tellusmuseum.org/', null, 'America/New_York', now()),
  ('The General Locomotive', 'the-general-locomotive', 'weird-history', 34.02398, -84.61431, 'Kennesaw', 'GA', 'The steam locomotive at the center of the Civil War''s Great Locomotive Chase is preserved inside the Southern Museum. Union raiders stole the General in 1862 and raced north along the Western & Atlantic Railroad while Confederate pursuers followed by train and on foot.', 'limited', 'https://southernmuseum.org/visit/', null, 'America/New_York', now()),
  ('The Big Chicken', 'the-big-chicken', 'roadside-oddities', 33.95139, -84.52028, 'Marietta', 'GA', 'A 56-foot-tall chicken-shaped KFC sign with moving eyes and beak has served as a local navigation landmark for decades. The structure is so embedded in Cobb County culture that residents routinely give directions relative to the Big Chicken.', 'open', 'https://visitmariettaga.com/eat/restaurants/the-big-chicken/', null, 'America/New_York', now()),
  ('Waffle House Museum', 'waffle-house-museum', 'museums', 33.7745, -84.27843, 'Decatur', 'GA', 'The original 1955 Waffle House has been restored as a museum with period counters, equipment, signage and company memorabilia. Access is scheduled rather than daily walk-in; as of September 2026, regular guided-tour availability is limited, so verify the official calendar before routing here.', 'limited', 'https://www.wafflehouse.com/museum/', null, 'America/New_York', now()),
  ('New Manchester Mill Ruins', 'new-manchester-mill-ruins', 'weird-history', 33.70182, -84.76793, 'Lithia Springs', 'GA', 'Stone walls from a textile mill destroyed during the Civil War stand beside Sweetwater Creek in the forest. A state-park trail reaches the ruins, which should be viewed from designated areas without climbing unstable masonry.', 'open', 'https://gastateparks.org/SweetwaterCreek', null, 'America/New_York', now()),
  ('Sope Creek Paper Mill Ruins', 'sope-creek-paper-mill-ruins', 'weird-history', 33.94033, -84.43765, 'Marietta', 'GA', 'The stacked-stone remains of a nineteenth-century paper mill sit along Sope Creek inside the Chattahoochee River National Recreation Area. The mill was destroyed during the Civil War, leaving a substantial maze of walls that now sits directly beside wooded trails.', 'open', 'https://www.nps.gov/places/marietta-paper-mill-ruins.htm', null, 'America/New_York', now()),
  ('Oakland Cemetery', 'oakland-cemetery', 'weird-history', 33.74862, -84.37165, 'Atlanta', 'GA', 'Atlanta''s historic garden cemetery combines elaborate Victorian monuments, mausoleums, gardens and the graves of major figures from the city''s history. The grounds function almost like an outdoor museum, with self-guided routes through architecture, symbolism and changing interpretations of Atlanta''s past.', 'open', 'https://www.oaklandcemetery.com/plan-your-visit', null, 'America/New_York', now()),
  ('Lion of Atlanta', 'lion-of-atlanta', 'weird-history', 33.7486, -84.3721, 'Atlanta', 'GA', 'A dying stone lion lies across the Confederate section of Oakland Cemetery as a monument to unknown Confederate dead. The sculpture is one of the cemetery''s most visually memorable monuments and can be visited during normal cemetery hours.', 'open', 'https://www.oaklandcemetery.com/', null, 'America/New_York', now()),
  ('Crypt of Civilization', 'crypt-of-civilization', 'weird-history', 33.87512, -84.33191, 'Brookhaven', 'GA', 'A sealed chamber beneath Oglethorpe University was packed in 1940 with records and objects intended to represent twentieth-century civilization. Its planned opening date is May 28, 8113; visitors cannot enter, but the sealed doorway and university interpretation make the extraordinary time scale tangible.', 'limited', 'https://oglethorpe.edu/about/history/crypt/', null, 'America/New_York', now()),
  ('Atlanta Monetary Museum', 'atlanta-monetary-museum', 'museums', 33.78206, -84.38466, 'Atlanta', 'GA', 'The Federal Reserve Bank of Atlanta operates a museum where visitors can see currency processing, historic money and exhibits explaining the banking system. Watching enormous quantities of cash move through an otherwise fortress-like institution gives this free weekday museum a distinctly unusual appeal.', 'limited', 'https://www.atlantafed.org/who-we-are/visit/atlanta-monetary-museum', null, 'America/New_York', now()),
  ('Center for Puppetry Arts', 'center-for-puppetry-arts', 'museums', 33.79276, -84.38982, 'Atlanta', 'GA', 'One of the country''s major puppetry institutions holds an extensive collection ranging from international traditions to Jim Henson characters. Familiar figures such as Muppets sit beside masks, marionettes and puppets from very different cultures, making the museum considerably stranger than a standard performing-arts stop.', 'limited', 'https://puppet.org/', null, 'America/New_York', now()),
  ('Rhodes Hall', 'rhodes-hall', 'roadside-oddities', 33.79594, -84.38834, 'Atlanta', 'GA', 'A Romanesque Revival mansion built from Stone Mountain granite rises improbably beside modern Peachtree Street. Nicknamed the ''Castle on Peachtree,'' it contains carved wood, stained glass and an interior far more medieval-looking than most Atlanta historic houses.', 'limited', 'https://www.georgiatrust.org/our-historic-sites/rhodes-hall/', null, 'America/New_York', now()),
  ('Doll''s Head Trail', 'dolls-head-trail', 'roadside-oddities', 33.68254, -84.34454, 'Atlanta', 'GA', 'A trail through Constitution Lakes Park contains folk-art installations assembled from discarded dolls, toys and other debris found on the property. The unsettling faces and handmade signs are intentionally created from material already present in the park; visitors should not bring outside junk to add.', 'open', 'https://www.atlantatrails.com/hiking-trails/dolls-head-trail-constitution-lakes-park/', null, 'America/New_York', now()),
  ('Westview Cemetery Abbey', 'westview-cemetery-abbey', 'weird-history', 33.7452, -84.4448, 'Atlanta', 'GA', 'A vast stone mausoleum and chapel complex known as the Abbey stands inside Atlanta''s Westview Cemetery. Its long interior corridors, stained glass and crypts produce a monumental atmosphere, but interior hours are narrower than cemetery gate hours and should be checked before visiting.', 'limited', 'https://www.westviewcemetery.com/hours.html', null, 'America/New_York', now()),
  ('Atlanta Cyclorama', 'atlanta-cyclorama', 'roadside-oddities', 33.84164, -84.38603, 'Atlanta', 'GA', 'The enormous circular painting depicting the Battle of Atlanta is displayed in a purpose-built gallery at the Atlanta History Center. The work wraps around the viewer and survives as both a Civil War artifact and an example of the once-popular panoramic entertainment format.', 'limited', 'https://www.atlantahistorycenter.com/exhibitions/cyclorama/', null, 'America/New_York', now()),
  ('Stone Mountain Memorial Carving', 'stone-mountain-memorial-carving', 'weird-history', 33.8055, -84.1474, 'Stone Mountain', 'GA', 'A gigantic relief of Confederate leaders Jefferson Davis, Robert E. Lee and Stonewall Jackson is carved into the exposed granite face of Stone Mountain. The park now interprets the carving within the history of Lost Cause commemoration and twentieth-century Confederate memorialization.', 'limited', 'https://stonemountainpark.com/activity/history-nature/memorial-carving/', null, 'America/New_York', now()),
  ('Stone Mountain Covered Bridge', 'stone-mountain-covered-bridge', 'weird-history', 33.8035, -84.13317, 'Stone Mountain', 'GA', 'A nineteenth-century covered bridge relocated from Athens spans the lake inside Stone Mountain Park. Its preserved wooden truss structure creates a separate historic stop within the larger park and can be routed independently from the mountain carving.', 'limited', 'https://stonemountainpark.com/', null, 'America/New_York', now()),
  ('Stone Mountain Grist Mill', 'stone-mountain-grist-mill', 'weird-history', 33.80625, -84.13486, 'Stone Mountain', 'GA', 'A red nineteenth-century gristmill relocated from Ellijay stands beside a stream and pond inside Stone Mountain Park. The small industrial structure is visually distinct from the park''s better-known monument and preserves another piece of Georgia''s relocated roadside history.', 'limited', 'https://stonemountainpark.com/', null, 'America/New_York', now()),
  ('Arabia Mountain', 'arabia-mountain', 'roadside-oddities', 33.66513, -84.11821, 'Lithonia', 'GA', 'A broad granite monadnock creates a stark, almost lunar landscape of exposed stone, solution pools and rare plant communities southeast of Atlanta. Trails cross the rock, but visitors should stay on durable surfaces and avoid fragile seasonal pools.', 'open', 'https://www.nps.gov/places/arabia-mountain-national-heritage-area.htm', null, 'America/New_York', now()),
  ('Monastery of the Holy Spirit', 'monastery-of-the-holy-spirit', 'roadside-oddities', 33.65424, -84.02661, 'Conyers', 'GA', 'A working Trappist monastery includes a striking concrete-and-stone church, quiet grounds, bonsai displays and monastic businesses. Visitors can experience a functioning contemplative community rather than a reconstructed religious site, while respecting areas reserved for the monks.', 'limited', 'https://www.trappist.net/', null, 'America/New_York', now()),
  ('Roswell Mill Ruins', 'roswell-mill-ruins', 'weird-history', 34.01318, -84.35873, 'Roswell', 'GA', 'Stone mill ruins and a historic dam survive along Vickery Creek where Roswell''s textile industry once operated. The mills were burned during the Civil War, and the remaining masonry is now reached by public trails and bridges inside the Chattahoochee recreation landscape.', 'open', 'https://www.visitroswellga.com/things-to-do/history/', null, 'America/New_York', now()),
  ('Southeastern Railway Museum', 'southeastern-railway-museum', 'roadside-oddities', 33.98672, -84.15435, 'Duluth', 'GA', 'Georgia''s official transportation history museum maintains a large outdoor collection of locomotives, passenger cars, cabooses, buses and other equipment. The ability to walk through rows of full-size historic machines makes the site feel closer to a railway graveyard than a conventional display hall.', 'limited', 'https://www.train-museum.org/plan-your-visit/', null, 'America/New_York', now()),
  ('Georgia Racing Hall of Fame', 'georgia-racing-hall-of-fame', 'museums', 34.41824, -84.11263, 'Dawsonville', 'GA', 'A museum dedicated to Georgia''s deep stock-car racing history, including the moonshine-running culture that fed early NASCAR. Race cars, memorabilia and stories of local drivers make it a strong companion stop to Dawsonville''s famous victory siren.', 'limited', 'https://georgiaracinghof.com/visit-us/', null, 'America/New_York', now()),
  ('Dawsonville Pool Room Victory Siren', 'dawsonville-pool-room-victory-siren', 'folklore', 34.42094, -84.11804, 'Dawsonville', 'GA', 'A loud siren on the Dawsonville Pool Room is traditionally sounded when a local Elliott family driver wins a major NASCAR race. The custom became part of Dawsonville identity, turning an ordinary downtown restaurant into a living piece of racing folklore.', 'limited', 'https://www.nascar.com/news-media/2014/04/19/another-elliott-brings-dawsonville-siren-to-life/', null, 'America/New_York', now()),
  ('Pine Mountain Gold Museum', 'pine-mountain-gold-museum', 'weird-history', 33.70676, -84.92195, 'Villa Rica', 'GA', 'A museum and park preserve mine remains, equipment and landscape from the gold industry west of Atlanta. Trails and outdoor features spread the history across the former mining property rather than containing it entirely inside a building.', 'limited', 'https://www.carrollcountyga.gov/313/Pine-Mountain-Gold-Museum', null, 'America/New_York', now()),
  ('American Prohibition Museum', 'american-prohibition-museum', 'museums', 32.08072, -81.09204, 'Savannah', 'GA', 'A museum devoted to America''s Prohibition era uses recreated speakeasies, figures, artifacts and displays about bootlegging, temperance and organized crime. The subject matter and theatrical staging make it one of Savannah''s more unusual indoor history stops.', 'limited', 'https://www.americanprohibitionmuseum.com/', null, 'America/New_York', now()),
  ('The Tree That Owns Itself', 'the-tree-that-owns-itself', 'folklore', 33.95504, -83.38238, 'Athens', 'GA', 'Local tradition holds that a University of Georgia professor loved this white oak so much that he deeded ownership of the tree and surrounding land to the tree itself. The original tree fell in 1942; the present tree was grown from one of its acorns and continues the beloved legal-fiction legend.', 'open', 'https://www.visitathensga.com/plan/faq/', null, 'America/New_York', now()),
  ('Double-Barreled Cannon', 'double-barreled-cannon', 'roadside-oddities', 33.95724, -83.37396, 'Athens', 'GA', 'An experimental Civil War cannon built to fire two balls connected by a chain sits outside Athens City Hall. The weapon never became practical, but the surviving double barrel is an instantly understandable piece of failed military engineering.', 'open', 'https://www.accgov.com/86/Double-Barreled-Cannon', null, 'America/New_York', now()),
  ('The Iron Horse', 'the-iron-horse', 'roadside-oddities', 33.72708, -83.30205, 'Watkinsville', 'GA', 'A roughly twelve-foot-tall welded steel horse created by artist Abbott Pattison became notorious after University of Georgia students repeatedly attacked it in the 1950s. Restored and reinstalled at UGA''s Iron Horse Plant Sciences Farm in 2024, it remains one of the state''s strangest public-art survivors.', 'roadside', 'https://news.uga.edu/iron-horse-gallops-back/', null, 'America/New_York', now()),
  ('Crawford W. Long Museum', 'crawford-w-long-museum', 'weird-history', 34.11818, -83.57298, 'Jefferson', 'GA', 'The museum explores physician Crawford W. Long''s pioneering use of ether anesthesia during surgery in 1842. Historic medical instruments and reconstructed spaces turn a major medical milestone into a suitably strange stop centered on the history of pain, surgery and experimentation.', 'limited', 'https://exploregeorgia.org/jefferson/arts-culture/museums/crawford-w-long-museum', null, 'America/New_York', now()),
  ('Porcelain and Decorative Arts Museum', 'porcelain-and-decorative-arts-museum', 'museums', 33.90243, -83.38125, 'Athens', 'GA', 'The State Botanical Garden of Georgia houses an unexpectedly extensive collection of porcelain, ceramics and decorative arts in a purpose-built museum. Elaborate objects and botanical forms make it a quieter but visually unusual detour within the garden.', 'limited', 'https://botgarden.uga.edu/porcelain-and-decorative-arts-museum/', null, 'America/New_York', now()),
  ('Eagle Tavern Museum', 'eagle-tavern-museum', 'roadside-oddities', 33.86394, -83.40938, 'Watkinsville', 'GA', 'A remarkably intact early nineteenth-century tavern preserves the sort of roadside lodging used by travelers before railroads reshaped Georgia. Period rooms and guided interpretation make it possible to see how strangers ate, slept and exchanged news along an early road corridor.', 'limited', 'https://exploregeorgia.org/watkinsville/general/historic-sites-trails-tours/eagle-tavern-museum', null, 'America/New_York', now()),
  ('Watson Mill Covered Bridge', 'watson-mill-covered-bridge', 'weird-history', 34.02687, -83.07483, 'Comer', 'GA', 'Georgia''s longest surviving covered bridge spans the South Fork Broad River inside Watson Mill Bridge State Park. The 1885 timber bridge still forms the visual centerpiece of the park and is one of the state''s strongest surviving pieces of old-road architecture.', 'limited', 'https://gastateparks.org/WatsonMillBridge', null, 'America/New_York', now()),
  ('Rock Eagle Effigy Mound', 'rock-eagle-effigy-mound', 'folklore', 33.41752, -83.38813, 'Eatonton', 'GA', 'Thousands of stones form a giant bird-shaped effigy on the ground, one of only a small number of large stone effigy mounds known in the region. Its exact age and purpose are not completely resolved, making Rock Eagle a genuine archaeological mystery rather than a modern roadside sculpture.', 'open', 'https://georgia4h.org/4-h-centers/rock-eagle-4-h-centers/about-rock-eagle/', null, 'America/New_York', now()),
  ('Rock Hawk Effigy and Outdoor Center', 'rock-hawk-effigy-and-outdoor-center', 'folklore', 33.34485, -83.17501, 'Eatonton', 'GA', 'Another large stone bird effigy lies east of Eatonton, surrounded by trails and interpretive displays. Like Rock Eagle, the original context of the stone figure is uncertain, but the preserved form is clearly distinct enough to justify its own OddWay route point.', 'open', 'https://rockhawk.org/effigies/', null, 'America/New_York', now()),
  ('Uncle Remus Museum', 'uncle-remus-museum', 'roadside-oddities', 33.34358, -83.38805, 'Eatonton', 'GA', 'A small museum in a former slave cabin interprets Joel Chandler Harris, the Uncle Remus stories and the complicated cultural history surrounding the tales. Modern visitors should approach the material with the museum''s historical context in mind rather than treating the fictional tradition as straightforward folklore.', 'limited', 'https://www.uncleremusmuseum.org/visit', null, 'America/New_York', now()),
  ('Andalusia Farm', 'andalusia-farm', 'weird-history', 33.11045, -83.25577, 'Milledgeville', 'GA', 'Flannery O''Connor lived and wrote at this farm, which became the setting and inspiration for parts of her Southern Gothic fiction. The preserved property, farm buildings and association with O''Connor''s famously roaming peafowl give it an especially strong OddWay literary atmosphere.', 'limited', 'https://www.nps.gov/places/andalusia-farm.htm', null, 'America/New_York', now()),
  ('Cedar Lane Cemetery — Central State Hospital', 'cedar-lane-cemetery-central-state-hospital', 'weird-history', 33.04075, -83.22078, 'Milledgeville', 'GA', 'Thousands of former Central State Hospital patients were buried in this cemetery, many once identified only by numbered markers. Preservation work has transformed the site into a memorial landscape, including a guardian-angel monument; visit respectfully and verify any current institutional access rules.', 'limited', 'https://frontpage.gcsu.edu/node/19794', null, 'America/New_York', now()),
  ('Memory Hill Cemetery', 'memory-hill-cemetery', 'weird-history', 33.07497, -83.2289, 'Milledgeville', 'GA', 'One of the original public squares in Georgia''s former capital became a cemetery containing politicians, soldiers, enslaved people, writers and other figures from state history. A self-guided route marks dozens of points of interest, including the grave of Flannery O''Connor.', 'open', 'https://www.visitmilledgeville.org/listings/memory-hill-cemetery/11/', null, 'America/New_York', now()),
  ('Ocmulgee Earth Lodge', 'ocmulgee-earth-lodge', 'weird-history', 32.84262, -83.60382, 'Macon', 'GA', 'A reconstructed earth lodge protects an original clay floor created by Mississippian people roughly a thousand years ago. Visitors enter through a low tunnel into the dark circular chamber, where molded seating and the eagle-shaped platform remain in place.', 'limited', 'https://www.nps.gov/ocmu/', null, 'America/New_York', now()),
  ('Great Temple Mound at Ocmulgee', 'great-temple-mound-at-ocmulgee', 'weird-history', 32.83679, -83.60836, 'Macon', 'GA', 'The largest mound at Ocmulgee rises above the floodplain and can be climbed by a designated staircase. It formed part of a major Indigenous ceremonial center, and the summit gives a clear sense of the enormous amount of earth moved to construct the site.', 'open', 'https://www.nps.gov/ocmu/', null, 'America/New_York', now()),
  ('Fort Hawkins', 'fort-hawkins', 'weird-history', 32.84918, -83.61141, 'Macon', 'GA', 'A reconstructed blockhouse and archaeological site mark the U.S. frontier fort established near Ocmulgee in 1806. Its location makes the uneasy boundary between the growing United States and the Muscogee (Creek) Nation physically visible in the modern city.', 'limited', 'https://exploregeorgia.org/macon/general/historic-sites-trails-tours/fort-hawkins', null, 'America/New_York', now()),
  ('Rose Hill Cemetery', 'rose-hill-cemetery', 'weird-history', 32.84981, -83.63571, 'Macon', 'GA', 'A dramatic nineteenth-century cemetery spreads across steep slopes above the Ocmulgee River, with winding roads, old mausoleums and graves tucked among trees. Its landscape and music history make it one of Georgia''s most atmospheric public cemeteries.', 'open', 'https://www.rosehillcemetery.org/', null, 'America/New_York', now()),
  ('Duane Allman and Berry Oakley Graves', 'duane-allman-and-berry-oakley-graves', 'weird-history', 32.848, -83.6335, 'Macon', 'GA', 'Allman Brothers Band members Duane Allman and Berry Oakley are buried near one another in Rose Hill Cemetery, a place closely tied to the band''s early Macon history. The graves remain major pilgrimage points; visitors should treat the surrounding active cemetery respectfully.', 'open', 'https://www.rosehillcemetery.org/', null, 'America/New_York', now()),
  ('The Allman Brothers Band Museum at The Big House', 'the-allman-brothers-band-museum-at-the-big-house', 'roadside-oddities', 32.84591, -83.65571, 'Macon', 'GA', 'The Tudor-style house where members of the Allman Brothers Band lived communally has been turned into a museum packed with instruments, clothing, posters and personal objects. It preserves the domestic setting behind one of the South''s most influential rock bands.', 'limited', 'https://thebighousemuseum.com/museum-tour/', null, 'America/New_York', now()),
  ('Hay House', 'hay-house', 'roadside-oddities', 32.84068, -83.63308, 'Macon', 'GA', 'An elaborate Italian Renaissance Revival mansion rises above downtown Macon with a cupola, curved staircase and unusually sophisticated nineteenth-century mechanical systems. Its scale and ornate interior earned it the nickname ''Palace of the South.''', 'limited', 'https://hayhouse.org/visit/', null, 'America/New_York', now()),
  ('Cannonball House', 'cannonball-house-macon', 'weird-history', 32.83993, -83.6321, 'Macon', 'GA', 'This Greek Revival home takes its modern name from damage caused by a Union artillery shell during the 1864 Battle of Dunlap Hill. Period rooms and surviving history turn the building into a rare civilian-scale remnant of wartime Macon.', 'limited', 'https://www.cannonballhouse.org/', null, 'America/New_York', now()),
  ('Capricorn Sound Studios & Museum', 'capricorn-sound-studios-museum', 'weird-history', 32.8367, -83.6315, 'Macon', 'GA', 'The restored recording studio associated with the Allman Brothers Band and the rise of Southern rock now combines active studio space with a museum. Original equipment, recordings and memorabilia preserve the atmosphere of a place where a distinct regional sound was built.', 'limited', 'https://capricorn.mercer.edu/', null, 'America/New_York', now()),
  ('Elberton Granite Museum & Exhibit', 'elberton-granite-museum-exhibit', 'roadside-oddities', 34.1112, -82.8675, 'Elberton', 'GA', 'A museum devoted to the granite industry explains how Elberton became one of America''s best-known centers for quarrying and monument production. Antique tools, stoneworking displays and the infamous ''Dutchy'' statue make the collection substantially stranger than a conventional local-history museum.', 'limited', 'https://www.elbertchamber.com/historical-sites.php', null, 'America/New_York', now()),
  ('Pexcho''s American Dime Museum', 'pexchos-american-dime-museum', 'museums', 33.47115, -81.96125, 'Augusta', 'GA', 'A modern revival of the old dime-museum tradition displays sideshow-style oddities, unusual artifacts, art and curiosities in downtown Augusta. Visits can require advance arrangement, so this is a check-ahead stop rather than a guaranteed walk-in museum.', 'limited', 'https://www.visitaugusta.com/listing/pexchos-american-dime-museum/804/', null, 'America/New_York', now()),
  ('Old Medical College', 'old-medical-college', 'weird-history', 33.47097, -81.97484, 'Augusta', 'GA', 'The imposing 1835 Greek Revival building served as the Medical College of Georgia''s first permanent home and later functioned as a Civil War hospital. Self-guided interior access is by appointment during limited weekday hours; the exterior remains an unusually monumental relic of early American medical education.', 'limited', 'https://historicaugusta.org/properties/old-medical-college-598-telfair/', null, 'America/New_York', now()),
  ('Magnolia Cemetery', 'magnolia-cemetery', 'weird-history', 33.46206, -81.95704, 'Augusta', 'GA', 'Established as a public cemetery in 1818, Magnolia holds roughly two centuries of Augusta history, including specialized religious sections, military graves and unusual monuments. One Revolutionary War veteran''s memorial incorporates a cannon standing upright in the ground.', 'open', 'https://www.augustaga.gov/352/Magnolia', null, 'America/New_York', now()),
  ('Confederate Powder Works Chimney', 'confederate-powder-works-chimney', 'weird-history', 33.48721, -81.99185, 'Augusta', 'GA', 'A tall brick chimney is the most prominent surviving structure from the massive Confederate powder works that operated along the Augusta Canal during the Civil War. The industrial complex disappeared, but the chimney was deliberately preserved as a monument and remains visible beside the canal corridor.', 'open', 'https://augustacanal.com/', null, 'America/New_York', now()),
  ('Laurel & Hardy Museum of Harlem', 'laurel-hardy-museum-of-harlem', 'museums', 33.4156, -82.3121, 'Harlem', 'GA', 'Harlem celebrates native son Oliver Hardy with a museum devoted to the legendary Laurel and Hardy comedy team. Posters, memorabilia and screenings turn a small Georgia town into an international pilgrimage stop for fans of early screen comedy.', 'limited', 'https://harlemmuseumandwelcomecenter.com/', null, 'America/New_York', now()),
  ('Sorrel-Weed House', 'sorrel-weed-house', 'haunted', 32.07409, -81.09406, 'Savannah', 'GA', 'An 1840s mansion on Madison Square is known both for Greek Revival architecture and for ghost-tour traditions that have accumulated around the property. Tours blend documented house history with Savannah''s paranormal storytelling, so supernatural claims should be understood as folklore rather than established fact.', 'limited', 'https://sorrelweedhouse.com/', null, 'America/New_York', now()),
  ('Mercer-Williams House Museum', 'mercer-williams-house-museum', 'weird-history', 32.07149, -81.09585, 'Savannah', 'GA', 'This carefully preserved mansion became internationally famous through the events recounted in ''Midnight in the Garden of Good and Evil.'' Tours focus on the architecture, antiques and collections while the building''s connection to the 1981 shooting of Danny Hansford adds a darker layer to its cultural history.', 'limited', 'https://www.mercerhouse.com/', null, 'America/New_York', now()),
  ('The Pirates'' House', 'the-pirates-house', 'folklore', 32.07809, -81.08388, 'Savannah', 'GA', 'A historic Savannah restaurant occupies buildings associated with the city''s early maritime district and generations of pirate and shanghaiing stories. Its tunnels and legends are part of local lore rather than proof of literal pirate kidnappings, but the building remains one of the city''s classic strange-history landmarks.', 'limited', 'https://thepirateshouse.com/', null, 'America/New_York', now()),
  ('Pasaquan', 'pasaquan', 'roadside-oddities', 32.1772, -84.5937, 'Buena Vista', 'GA', 'Visionary artist St. EOM, born Eddie Owens Martin, transformed his rural home into a brightly colored environment of walls, faces, figures and invented symbols. Columbus State University now preserves the site, allowing visitors to walk through one of the most singular outsider-art environments in the United States.', 'limited', 'https://www.pasaquan.com/', null, 'America/New_York', now()),
  ('National Civil War Naval Museum', 'national-civil-war-naval-museum', 'roadside-oddities', 32.44705, -84.97979, 'Columbus', 'GA', 'A museum devoted to Civil War naval warfare displays major ship remains, full-scale reconstructions, weapons and artifacts from river and coastal combat. The enormous hull sections give the collection a scale far beyond a typical military display case.', 'limited', 'https://www.portcolumbus.org/', null, 'America/New_York', now()),
  ('Lunch Box Museum', 'lunch-box-museum', 'museums', 32.5245, -84.9577, 'Columbus', 'GA', 'A private collection of vintage metal lunch boxes, thermoses and related pop-culture memorabilia fills part of the River Market Antique Mall complex. The museum turns decades of disposable school-day objects into a dense visual history of television, movies and advertising.', 'limited', 'https://visitcolumbusga.com/', null, 'America/New_York', now()),
  ('Coca-Cola Space Science Center', 'coca-cola-space-science-center', 'roadside-oddities', 32.45984, -84.99526, 'Columbus', 'GA', 'Columbus State University''s science center combines a planetarium with NASA artifacts, interactive exhibits and space-flight hardware. It is particularly useful for OddWay routes through western Georgia because the collection brings real space-history material into an unexpected downtown location.', 'limited', 'https://www.ccssc.org/', null, 'America/New_York', now()),
  ('Dr. John Pemberton''s Grave — Linwood Cemetery', 'dr-john-pembertons-grave-linwood-cemetery', 'weird-history', 32.47375, -84.9683, 'Columbus', 'GA', 'The inventor of Coca-Cola, pharmacist John Stith Pemberton, is buried in Columbus''s historic Linwood Cemetery. His grave creates a quiet counterpoint to one of the world''s most recognizable brands and is specifically noted by the city among the cemetery''s notable burials.', 'open', 'https://columbusga.org/publicworks/Divisions/Cemeteries', null, 'America/New_York', now()),
  ('Kadie the Cow', 'kadie-the-cow', 'roadside-oddities', 32.4633, -84.994, 'Columbus', 'GA', 'A roughly twenty-foot-tall fiberglass cow that once advertised Kinnett Dairies survives as a beloved Columbus landmark. The giant bovine has been moved and restored over the years, but the city continues to preserve her as a piece of local roadside identity.', 'open', 'https://visitcolumbusga.com/visit/things-to-do/kadie-the-cow/', null, 'America/New_York', now()),
  ('Roosevelt''s Little White House', 'roosevelts-little-white-house', 'weird-history', 32.88139, -84.68764, 'Warm Springs', 'GA', 'Franklin D. Roosevelt''s modest Georgia retreat preserves the setting where he sought relief from polio and where he died in 1945. As of September 2026, the main historic-house area is undergoing renovation while the museum and portions of the grounds remain available, so check the state site''s current access notice before visiting.', 'limited', 'https://gastateparks.org/LittleWhiteHouse', null, 'America/New_York', now()),
  ('Indian Springs Spring House', 'indian-springs-spring-house', 'roadside-oddities', 33.2455, -83.9205, 'Flovilla', 'GA', 'A stone spring house built by the Civilian Conservation Corps encloses the mineral-rich water that made Indian Springs a destination long before modern state parks. Visitors can still sample the distinctive sulfurous water, turning a roadside park stop into a literal taste of Georgia geology.', 'open', 'https://gastateparks.org/IndianSprings', null, 'America/New_York', now()),
  ('Providence Canyon State Park', 'providence-canyon-state-park', 'roadside-oddities', 32.06445, -84.92191, 'Lumpkin', 'GA', 'Deep red, orange and pink gullies form Georgia''s so-called Little Grand Canyon. The dramatic erosion was accelerated by poor nineteenth-century farming practices, making the landscape both visually spectacular and an enormous accidental monument to human-caused soil loss.', 'limited', 'https://gastateparks.org/ProvidenceCanyon', null, 'America/New_York', now()),
  ('Kolomoki Mounds', 'kolomoki-mounds', 'weird-history', 31.46841, -84.94852, 'Blakely', 'GA', 'One of the Southeast''s largest Woodland-period mound complexes includes ceremonial and burial mounds arranged around a broad plaza. The scale and age of the earthworks make Kolomoki a major archaeological stop well outside Georgia''s better-known tourism corridors.', 'limited', 'https://gastateparks.org/kolomoki-mounds', null, 'America/New_York', now()),
  ('Andersonville Prison Stockade Site', 'andersonville-prison-stockade-site', 'weird-history', 32.19832, -84.12989, 'Andersonville', 'GA', 'Earthworks, reconstructed stockade sections and the open prison landscape mark Camp Sumter, where nearly 13,000 Union prisoners died during the Civil War. NPS interpretation focuses on the brutal conditions, prisoners'' experiences and the broader history of captivity.', 'open', 'https://www.nps.gov/ande/', null, 'America/New_York', now()),
  ('National Prisoner of War Museum', 'national-prisoner-of-war-museum', 'weird-history', 32.19751, -84.12712, 'Andersonville', 'GA', 'This national museum uses Andersonville as a starting point to interpret American prisoners of war across multiple conflicts. Artifacts and personal testimony expand the story far beyond the Civil War prison visible outside.', 'limited', 'https://www.nps.gov/ande/', null, 'America/New_York', now()),
  ('Andersonville National Cemetery', 'andersonville-national-cemetery', 'weird-history', 32.20076, -84.1305, 'Andersonville', 'GA', 'Long rows of closely spaced graves preserve the most visually immediate evidence of the deaths at Andersonville prison, while the cemetery remains an active national burial ground. Visitors should treat it as both a historic site and a place of ongoing military remembrance.', 'open', 'https://www.nps.gov/places/andersonville-national-cemetery.htm', null, 'America/New_York', now()),
  ('Drummer Boy Civil War Museum', 'drummer-boy-civil-war-museum', 'museums', 32.196, -84.1413, 'Andersonville', 'GA', 'A small private museum in the village of Andersonville packs Civil War uniforms, weapons, photographs and relics into a more intimate collection than the nearby federal sites. It works best as a companion stop after the prison and national cemetery.', 'limited', 'https://www.andersonvillegeorgia.info/the-museum.html', null, 'America/New_York', now()),
  ('Windsor Hotel', 'windsor-hotel', 'roadside-oddities', 32.07194, -84.23389, 'Americus', 'GA', 'A massive 1892 Victorian hotel fills an entire city block with towers, balconies and a dramatic interior atrium. The building remains a functioning hotel, allowing travelers to experience the ornate architecture as a living property rather than a sealed historic house.', 'limited', 'https://www.windsor-americus.com/', null, 'America/New_York', now()),
  ('Georgia Rural Telephone Museum', 'georgia-rural-telephone-museum', 'museums', 31.9508, -84.0868, 'Leslie', 'GA', 'A former cotton warehouse holds an enormous collection of telephones, switchboards and telecommunications equipment dating back to the earliest years of the technology. The sheer number of obsolete devices makes it one of Georgia''s strongest single-subject curiosity museums.', 'limited', 'https://exploregeorgia.org/leslie/visitors-services/cities-towns/leslie', null, 'America/New_York', now()),
  ('Jimmy Carter Smiling Peanut', 'jimmy-carter-smiling-peanut', 'roadside-oddities', 32.0314, -84.3921, 'Plains', 'GA', 'A giant grinning peanut with oversized teeth was created during Jimmy Carter''s 1976 presidential campaign and became an enduring Plains landmark. The National Park Service now interprets the roadside peanut as part of the visual culture surrounding Carter''s rise from Georgia farmer to president.', 'roadside', 'https://www.nps.gov/jica/planyourvisit/the-mighty-peanut.htm', null, 'America/New_York', now()),
  ('Flint RiverQuarium Blue Hole', 'flint-riverquarium-blue-hole', 'roadside-oddities', 31.5785, -84.1495, 'Albany', 'GA', 'The RiverQuarium''s centerpiece is a 175,000-gallon open-air exhibit modeled on Southwest Georgia''s blue-hole springs. More than a hundred kinds of aquatic animals inhabit the habitat, giving visitors an unusually direct look at the hidden freshwater systems beneath the region.', 'limited', 'https://flintriverquarium.com/explore/blue-hole-spring', null, 'America/New_York', now()),
  ('Jefferson Davis Memorial Historic Site', 'jefferson-davis-memorial-historic-site', 'weird-history', 31.66373, -83.38703, 'Irwinville', 'GA', 'A monument and museum mark the location where Confederate president Jefferson Davis was captured by Union troops in May 1865. The preserved site interprets the final collapse of the Confederate government rather than functioning solely as a memorial.', 'limited', 'https://gastateparks.org/JeffersonDavisMemorial', null, 'America/New_York', now()),
  ('Blue & Gray Museum', 'blue-gray-museum', 'roadside-oddities', 31.71579, -83.25788, 'Fitzgerald', 'GA', 'Fitzgerald was founded by Union veterans in the postwar South and deliberately developed a civic identity around reconciliation. The city-operated museum fills a historic depot with artifacts telling that unusual origin story and the community that grew from it.', 'limited', 'https://www.fitzgeraldga.org/blue-and-gray-museum.html', null, 'America/New_York', now()),
  ('Fitzgerald Wild Chickens', 'fitzgerald-wild-chickens', 'roadside-oddities', 31.7149, -83.2527, 'Fitzgerald', 'GA', 'Free-roaming chickens descended in part from red junglefowl released in the area have become a recognizable feature of Fitzgerald streets and parks. The city celebrates the birds with an annual Wild Chicken Festival, making the flock an active local tradition rather than a one-off sighting.', 'open', 'https://wildchickenfestival.com/', null, 'America/New_York', now()),
  ('Georgia Museum of Agriculture', 'georgia-museum-of-agriculture', 'museums', 31.46522, -83.53529, 'Tifton', 'GA', 'A large living-history complex operated by Abraham Baldwin Agricultural College includes historic farm buildings, demonstrations, equipment and a recreated rural town. Old machinery and working agricultural processes make it more tactile and unusual than a standard regional museum.', 'limited', 'https://gma.abac.edu/', null, 'America/New_York', now()),
  ('Radium Springs Gardens', 'radium-springs-gardens', 'roadside-oddities', 31.5274, -84.1367, 'Albany', 'GA', 'Clear blue water rises from one of Georgia''s largest natural springs at the site of a former resort whose name traded on the once-fashionable idea of radium water. Gardens and surviving architectural traces now surround the spring, preserving both the geology and the strange health-resort history.', 'open', 'https://www.dougherty.ga.us/VisitorsCommunity/Things-To-Do/Parks-Recreation', null, 'America/New_York', now()),
  ('Ray Charles Plaza', 'ray-charles-plaza', 'roadside-oddities', 31.57851, -84.15574, 'Albany', 'GA', 'A rotating bronze sculpture of Ray Charles sits at a piano in a riverside plaza, with his music incorporated into the memorial experience. The kinetic, musical monument gives Albany a much more interactive tribute than a conventional standing statue.', 'open', 'https://downtown.albanyga.gov/Attractions', null, 'America/New_York', now()),
  ('Thronateeska Heritage Center', 'thronateeska-heritage-center', 'museums', 31.58149, -84.14948, 'Albany', 'GA', 'A complex of historic railroad buildings combines regional history, science exhibits and a planetarium. Its mix of trains, artifacts and astronomy makes it an unusually broad curiosity stop within a compact downtown campus.', 'limited', 'https://heritagecenter.org/visit', null, 'America/New_York', now()),
  ('Southern Forest World — Stuckie the Mummified Dog', 'southern-forest-world-stuckie-the-mummified-dog', 'museums', 31.2349, -82.38316, 'Waycross', 'GA', 'This forestry museum''s most famous exhibit is Stuckie, a dog whose naturally mummified body was found lodged inside a hollow tree decades after it died. The museum also contains logging equipment and forest-industry displays, but Stuckie''s bizarre preservation makes the stop unmistakably OddWay.', 'limited', 'https://southernforestworld.org/', null, 'America/New_York', now()),
  ('Okefenokee Swamp Park', 'okefenokee-swamp-park', 'roadside-oddities', 31.05779, -82.27247, 'Waycross', 'GA', 'A long-running gateway attraction offers boardwalks, boat excursions, wildlife viewing and interpretation of the Okefenokee''s enormous blackwater wetland. Alligators, cypress forests and peat-stained water create one of the state''s most distinctive natural environments.', 'limited', 'https://okeswamp.org/', null, 'America/New_York', now()),
  ('Suwannee Canal Recreation Area', 'suwannee-canal-recreation-area', 'roadside-oddities', 30.73995, -82.12706, 'Folkston', 'GA', 'The eastern entrance to Okefenokee National Wildlife Refuge follows the remains of a nineteenth-century attempt to drain the swamp through the Suwannee Canal. Boardwalks, trails and boat access now turn that failed engineering project into a gateway to protected wilderness.', 'limited', 'https://www.fws.gov/refuge/okefenokee/visit-us', null, 'America/New_York', now()),
  ('Chesser Island Homestead', 'chesser-island-homestead', 'weird-history', 30.71541, -82.15544, 'Folkston', 'GA', 'A preserved homestead inside Okefenokee National Wildlife Refuge shows how families lived on sandy islands surrounded by swamp. The house, outbuildings and demonstrations provide a human-scale counterpoint to the huge wetland around it.', 'limited', 'https://www.fws.gov/refuge/okefenokee/visit-us', null, 'America/New_York', now()),
  ('Okefenokee State Park', 'okefenokee-state-park', 'roadside-oddities', 30.82556, -82.36194, 'Fargo', 'GA', 'The western Okefenokee access point formerly known as Stephen C. Foster State Park sits deep inside the refuge and is famous for extraordinarily dark night skies. The combination of swamp wildlife, isolation and near-total darkness makes overnight visits especially atmospheric.', 'limited', 'https://www.fws.gov/partner/okefenokee-state-park', null, 'America/New_York', now()),
  ('Obediah''s Okefenok', 'obediahs-okefenok', 'weird-history', 31.21, -82.31, 'Waycross', 'GA', 'A privately maintained homestead museum preserves regional tools, buildings and material culture connected to life around the Okefenokee. Visits are by appointment rather than standard daily hours, so contact the site before routing travelers to the property.', 'limited', 'https://www.obediahsokefenokevent.com/', null, 'America/New_York', now()),
  ('Folkston Funnel Train-Watching Platform', 'folkston-funnel-train-watching-platform', 'roadside-oddities', 30.8307, -82.0118, 'Folkston', 'GA', 'An elevated public platform overlooks the busy rail corridor where trains funnel toward and from Florida. The town embraced railfan culture with shelter, information and a dedicated viewing area, turning freight traffic into an around-the-clock roadside attraction.', 'open', 'https://charltoncountyga.us/236/Folkston-Funnel', null, 'America/New_York', now()),
  ('Lapham-Patterson House', 'lapham-patterson-house', 'roadside-oddities', 30.8367, -83.9768, 'Thomasville', 'GA', 'Built for a survivor of the Great Chicago Fire, this wildly asymmetrical Victorian house contains odd angles, unusual windows, elaborate woodwork and design choices reportedly influenced by its owner''s fear of fire. Guided access is limited, making advance schedule checks important.', 'limited', 'https://gastateparks.org/LaphamPattersonHouse', null, 'America/New_York', now()),
  ('The Big Oak', 'the-big-oak', 'roadside-oddities', 30.8379, -83.9783, 'Thomasville', 'GA', 'A huge live oak dating to roughly the seventeenth century spreads limbs across a small downtown park. The city lists a limb span of more than 165 feet and a trunk circumference over 26 feet, giving travelers a genuine natural giant rather than a fiberglass roadside imitation.', 'open', 'https://thomasville.org/parks-and-recreation', null, 'America/New_York', now()),
  ('Altie Sea Monster Replica', 'altie-sea-monster-replica', 'cryptids', 31.401, -81.43, 'Darien', 'GA', 'The Darien-McIntosh visitor center displays a full-size interpretation of Altamaha-ha, or ''Altie,'' the serpentine creature long reported in stories from the Altamaha River and nearby coast. The replica gives travelers a physical destination for a legend that otherwise has no single routeable location.', 'limited', 'https://exploregeorgia.org/darien/food-drink/cafes-coffeehouses-tea-rooms/darien-mcintosh-regional-visitor-information-center', null, 'America/New_York', now()),
  ('Fort King George', 'fort-king-george', 'weird-history', 31.361, -81.4167, 'Darien', 'GA', 'Reconstructed blockhouses and earthworks stand on the site of the British Empire''s southernmost North American outpost in the early eighteenth century. The marsh-edge fort interprets disease, conflict and the harsh conditions faced by soldiers on this remote frontier.', 'limited', 'https://gastateparks.org/FortKingGeorge', null, 'America/New_York', now()),
  ('Reynolds Mansion on Sapelo Island', 'reynolds-mansion-on-sapelo-island', 'weird-history', 31.3929, -81.2813, 'Sapelo Island', 'GA', 'A large mansion on remote Sapelo Island passed through wealthy owners including tobacco heir R.J. Reynolds and now operates under Georgia state management. Access requires planning around the island ferry and scheduled tours, making the journey itself part of the OddWay experience.', 'limited', 'https://gastateparks.org/ReynoldsMansion', null, 'America/New_York', now()),
  ('Sapelo Island Lighthouse', 'sapelo-island-lighthouse', 'weird-history', 31.39127, -81.28565, 'Sapelo Island', 'GA', 'A restored red-and-white lighthouse stands near the southern end of Sapelo Island beside marsh and maritime forest. Because reaching Sapelo generally requires ferry transportation and controlled island access, this is a destination to plan rather than an impromptu roadside stop.', 'limited', 'https://gastateparks.org/ReynoldsMansion', null, 'America/New_York', now()),
  ('Fort Frederica National Monument', 'fort-frederica-national-monument', 'weird-history', 31.22147, -81.39452, 'St. Simons Island', 'GA', 'Tabby ruins and street traces mark the fortified British town founded in the 1730s to defend Georgia against Spanish Florida. The remains spread under enormous live oaks, allowing visitors to walk the outline of a colonial settlement that largely vanished after its military purpose faded.', 'open', 'https://www.nps.gov/fofr/', null, 'America/New_York', now()),
  ('Bloody Marsh Battle Site', 'bloody-marsh-battle-site', 'weird-history', 31.15685, -81.37963, 'St. Simons Island', 'GA', 'A small preserved landscape marks the 1742 fighting that helped end Spain''s attempt to push north into British Georgia. The dramatic name outgrew the scale of the engagement, making the site a useful place to separate later legend from the documented Battle of Bloody Marsh.', 'open', 'https://www.nps.gov/places/bloody-marsh.htm', null, 'America/New_York', now()),
  ('St. Simons Lighthouse Museum', 'st-simons-lighthouse-museum', 'weird-history', 31.1341, -81.3942, 'St. Simons Island', 'GA', 'A working lighthouse and keeper''s dwelling preserve maritime history at the island''s southern end. Visitors can climb the tower during operating hours, making the functioning nineteenth-century light a more active experience than simply viewing it from the road.', 'limited', 'https://www.coastalgeorgiahistory.org/visit/st-simons-lighthouse-museum/', null, 'America/New_York', now()),
  ('St. Simons Tree Spirits', 'st-simons-tree-spirits', 'roadside-oddities', 31.1357, -81.3881, 'St. Simons Island', 'GA', 'Carved faces emerge from live oaks around St. Simons, a public-art tradition begun by sculptor Keith Jennings and continued by other carvers. The figures are scattered rather than concentrated at one site; the island visitor information network can help travelers locate publicly viewable examples.', 'open', 'https://www.goldenisles.com/blog/post/the-tree-spirits-of-st-simons-island/', null, 'America/New_York', now()),
  ('Lover''s Oak', 'lovers-oak', 'roadside-oddities', 31.14995, -81.49149, 'Brunswick', 'GA', 'A huge live oak spreads over the intersection of Albany and Prince streets and has long been wrapped in local romantic lore. Whatever the legends, the tree itself is an extraordinary urban survivor whose enormous limbs dominate the street around it.', 'open', 'https://www.goldenisles.com/', null, 'America/New_York', now()),
  ('Horton House Ruins', 'horton-house-ruins', 'weird-history', 31.10189, -81.41439, 'Jekyll Island', 'GA', 'Tabby walls from Major William Horton''s eighteenth-century plantation house survive beside the road on Jekyll Island. The roofless structure exposes the shell-based tabby construction method in a way that is easy to see without entering an unstable ruin.', 'open', 'https://www.jekyllisland.com/history/sites/horton-house/', null, 'America/New_York', now()),
  ('Driftwood Beach', 'driftwood-beach', 'roadside-oddities', 31.10422, -81.40662, 'Jekyll Island', 'GA', 'Weathered trunks and skeletal trees cover this eroding shoreline, creating a natural landscape that looks like a forest graveyard at low tide. The trees are the remains of a maritime forest lost as the island''s north end gradually eroded.', 'open', 'https://www.jekyllisland.com/activities/beaches/driftwood-beach/', null, 'America/New_York', now()),
  ('Georgia Sea Turtle Center', 'georgia-sea-turtle-center', 'roadside-oddities', 31.05995, -81.41967, 'Jekyll Island', 'GA', 'Georgia''s sea-turtle rehabilitation and education center allows visitors to see conservation work, exhibits and recovering turtles. The hospital setting turns wildlife rescue into a routeable experience rather than relying on unpredictable beach sightings.', 'limited', 'https://www.jekyllisland.com/activities/georgia-sea-turtle-center/', null, 'America/New_York', now()),
  ('Wanderer Memory Trail', 'wanderer-memory-trail', 'weird-history', 31.02099, -81.43257, 'Jekyll Island', 'GA', 'A waterfront trail interprets the Wanderer, one of the last known ships to illegally bring captive Africans into the United States after the transatlantic slave trade had been outlawed. Sculptural and interpretive installations connect the specific landing site to the people forced ashore here in 1858.', 'open', 'https://www.jekyllisland.com/history/sites/wanderer-memory-trail/', null, 'America/New_York', now()),
  ('Dungeness Ruins', 'dungeness-ruins', 'weird-history', 30.8585, -81.4525, 'Cumberland Island', 'GA', 'The roofless remains of the Carnegie family''s enormous Dungeness mansion stand among palms, live oaks and roaming wildlife on Cumberland Island. Reaching the island requires ferry or private boat access, and the ruins are explored on foot from the developed south-end area.', 'limited', 'https://www.nps.gov/cuis/planyourvisit/on-island.htm', null, 'America/New_York', now()),
  ('Plum Orchard Mansion', 'plum-orchard-mansion', 'weird-history', 30.85593, -81.46524, 'Cumberland Island', 'GA', 'A sprawling Carnegie-era mansion survives deeper on Cumberland Island with period interiors and unusually complex domestic systems. Access depends on island transportation and scheduled tours, so travelers should plan this separately from a quick Dungeness visit.', 'limited', 'https://www.nps.gov/places/plum-orchard.htm', null, 'America/New_York', now()),
  ('First African Baptist Church — Cumberland Island', 'first-african-baptist-church-cumberland-island', 'weird-history', 30.92378, -81.4347, 'Cumberland Island', 'GA', 'A tiny church in the isolated Settlement at Cumberland''s north end represents the island''s African American community after emancipation. Its remoteness is substantial: visitors generally need bicycles, a tour or other arranged transportation to reach it from the ferry landing.', 'limited', 'https://www.nps.gov/places/first-african-baptist-church.htm', null, 'America/New_York', now()),
  ('The Smallest Church in America', 'the-smallest-church-in-america', 'roadside-oddities', 31.47, -81.365, 'Darien', 'GA', 'Christ''s Chapel in Memory Park is a roughly 190-square-foot roadside sanctuary built in 1949 as a quiet place for travelers. After a 2015 arson fire destroyed the original, the tiny church was rebuilt and continues to welcome visitors along U.S. 17.', 'open', 'https://exploregeorgia.org/darien/general/historic-sites-trails-tours/the-smallest-church-in-america', null, 'America/New_York', now()),
  ('Wormsloe State Historic Site', 'wormsloe-state-historic-site', 'weird-history', 31.97, -81.056, 'Savannah', 'GA', 'A mile-long avenue of live oaks leads to the former estate of colonial official Noble Jones, where tabby ruins from an early fortified house survive. The dramatic entrance is only part of the stop; trails and interpretation continue into the historic property beyond the gate.', 'limited', 'https://gastateparks.org/Wormsloe', null, 'America/New_York', now()),
  ('Bonaventure Cemetery', 'bonaventure-cemetery', 'weird-history', 32.0453, -81.05, 'Savannah', 'GA', 'Spanish moss, enormous live oaks, elaborate statuary and family plots fill Savannah''s most famous cemetery. Its landscape became internationally recognizable through ''Midnight in the Garden of Good and Evil,'' but the active cemetery contains far more history than the book''s association alone.', 'open', 'https://www.savannahga.gov/864/Bonaventure-Cemetery', null, 'America/New_York', now()),
  ('Little Gracie Watson''s Grave', 'little-gracie-watsons-grave', 'weird-history', 32.04288, -81.04504, 'Savannah', 'GA', 'A life-size marble statue of six-year-old Gracie Watson marks one of Bonaventure Cemetery''s most visited graves. The sculpture''s intimate realism and the child''s association with Savannah''s Pulaski House hotel helped generate generations of local ghost stories, which should be treated as folklore.', 'open', 'https://www.bonaventurehistorical.org/little-gracie-watson/', null, 'America/New_York', now()),
  ('Colonial Park Cemetery', 'colonial-park-cemetery', 'weird-history', 32.073, -81.0883, 'Savannah', 'GA', 'Savannah''s old city cemetery contains eighteenth- and nineteenth-century graves, damaged stones and monuments tied to epidemics, duels and the city''s colonial era. It is now a public park with gate hours, making dense early burial history accessible directly in the historic district.', 'open', 'https://www.savannahga.gov/879/Colonial-Park-Cemetery', null, 'America/New_York', now()),
  ('Fort Pulaski National Monument', 'fort-pulaski-national-monument', 'weird-history', 32.0348, -80.9436, 'Savannah', 'GA', 'A massive brick coastal fort on Cockspur Island became a landmark in military technology when rifled Union artillery breached its walls during the Civil War. Visitors can walk through casemates, tunnels and damaged masonry while seeing exactly why older brick fortifications suddenly became obsolete.', 'limited', 'https://home.nps.gov/fopu/planyourvisit/basicinfo.htm', null, 'America/New_York', now()),
  ('Old Fort Jackson', 'old-fort-jackson', 'weird-history', 32.0817, -81.0378, 'Savannah', 'GA', 'A restored brick fort stands directly on the Savannah River east of downtown and remains one of Georgia''s oldest surviving masonry forts. Daily programming often includes cannon demonstrations, adding sound and movement to a site that still overlooks modern ships passing the river.', 'limited', 'https://chsgeorgia.org/old-fort-jackson/', null, 'America/New_York', now()),
  ('Graveface Museum', 'graveface-museum', 'museums', 32.08036, -81.08697, 'Savannah', 'GA', 'A downtown museum combines true-crime material, cult history, sideshow objects, unusual taxidermy and an extensive pinball collection. The deliberately macabre mix makes it one of the clearest OddWay-category museums in Savannah rather than a generic ghost-tour stop.', 'limited', 'https://gravefacemuseum.com/', null, 'America/New_York', now()),
  ('Tybee Island Light Station & Museum', 'tybee-island-light-station-museum', 'weird-history', 32.0227, -80.8456, 'Tybee Island', 'GA', 'Georgia''s oldest and tallest lighthouse complex remains active on Tybee Island, with a climbable tower and preserved keeper buildings. The site combines maritime engineering, coastal history and a physically demanding tower climb into a strong final stop for the state.', 'limited', 'https://www.tybeelighthouse.org/', null, 'America/New_York', now())
on conflict (slug) do update set
  description   = excluded.description,
  public_access = excluded.public_access,
  source        = excluded.source,
  website       = excluded.website,
  verified_at   = excluded.verified_at;

select count(*) as georgia from public.stops where state = 'GA';
